#!/usr/bin/env python3
"""
Generate .github/CODEOWNERS from scripts/ownership_map.py.
Follows the GitHub CODEOWNERS precedence rule: last matching pattern takes priority.
Broader directory patterns are placed first; specific file overrides follow.
"""

from pathlib import Path
import sys

# Ensure scripts dir is importable
repo_root = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(repo_root))

from scripts.ownership_map import OWNERSHIP_MAP, GITHUB_HANDLES


def generate_codeowners() -> str:
    lines = [
        "# This file is automatically generated by scripts/gen_codeowners.py from scripts/ownership_map.py.",
        "# DO NOT EDIT DIRECTLY. Run 'python scripts/gen_codeowners.py' to regenerate.",
        "#",
        "# NOTE: GitHub CODEOWNERS checks are only enforced if repository branch protection",
        "# requires Code Owner review. In local development and CI, scripts/check_ownership.py",
        "# is the authoritative pre-commit and pre-push enforcement gate.",
        "#",
        "# Precedence: Later patterns override earlier ones.",
        "",
        "# =============================================================================",
        "# Global Fallback (Integrator Hat: Hoang)",
        "# =============================================================================",
        f"* @{GITHUB_HANDLES['integrator']}",
        "",
    ]

    # Partition into broad directory patterns vs specific file patterns
    broad_patterns = []
    specific_patterns = []

    for owner, patterns in OWNERSHIP_MAP.items():
        handle = GITHUB_HANDLES.get(owner)
        for pattern in patterns:
            # Format pattern for git/codeowners (ensure leading slash if needed)
            co_pattern = f"/{pattern}" if not pattern.startswith("/") else pattern
            entry = (owner, co_pattern, handle)
            if pattern.endswith("/*") or pattern.endswith("/**"):
                broad_patterns.append(entry)
            else:
                specific_patterns.append(entry)

    # 1. Broad Directory Patterns
    lines.append("# =============================================================================")
    lines.append("# Broad Directory Patterns")
    lines.append("# =============================================================================")
    for owner, pattern, handle in broad_patterns:
        if handle:
            lines.append(f"{pattern:<45} @{handle}  # {owner}")
        else:
            lines.append(f"# TODO: Set GitHub handle for {owner}")
            lines.append(f"# {pattern:<43} @[C_USERNAME]")

    lines.append("")
    lines.append("# =============================================================================")
    lines.append("# Specific File Overrides")
    lines.append("# =============================================================================")
    for owner, pattern, handle in specific_patterns:
        if handle:
            lines.append(f"{pattern:<45} @{handle}  # {owner}")
        else:
            lines.append(f"# TODO: Set GitHub handle for {owner}")
            lines.append(f"# {pattern:<43} @[C_USERNAME]")

    lines.append("")
    return "\n".join(lines)


def main():
    codeowners_path = repo_root / ".github" / "CODEOWNERS"
    content = generate_codeowners()
    codeowners_path.write_text(content, encoding="utf-8")
    print(f"[OK] Generated {codeowners_path} from scripts/ownership_map.py")


if __name__ == "__main__":
    main()
